using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class B3RepairLodExport {
 public static object Run(){if(Application.isPlaying)throw new Exception("Wait for user Play to end");string h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B3_StructureRepair/"));Directory.CreateDirectory(h+"mesh_data");var cat=JArray.Parse(File.ReadAllText(h+"catalog.json"));var plan=new JArray();foreach(var c in cat.Where(c=>((string)c["asset"]).Contains("/Props/")&&(int)c["triangles"]>9000)){string asset=(string)c["asset"],name="BRL_"+(string)c["name"];var mf=AssetDatabase.LoadAssetAtPath<GameObject>(asset).GetComponentsInChildren<MeshFilter>().Single();var m=mf.sharedMesh;var r=mf.GetComponent<MeshRenderer>();using(var w=new BinaryWriter(File.Create(h+"mesh_data/"+name+".bin"))){var vs=m.vertices;var ns=m.normals;var uv=m.uv;w.Write(vs.Length);w.Write(m.subMeshCount);for(int i=0;i<vs.Length;i++){w.Write(vs[i].x);w.Write(vs[i].y);w.Write(vs[i].z);w.Write(ns[i].x);w.Write(ns[i].y);w.Write(ns[i].z);w.Write(uv.Length==vs.Length?uv[i].x:0);w.Write(uv.Length==vs.Length?uv[i].y:0);}for(int j=0;j<m.subMeshCount;j++){var tr=m.GetTriangles(j);w.Write(tr.Length);foreach(int n in tr)w.Write(n);}}plan.Add(JObject.FromObject(new{asset,name,mesh=m.name,tri=m.triangles.Length/3,materialNames=r.sharedMaterials.Select(x=>x.name).ToArray(),materials=r.sharedMaterials.Select(AssetDatabase.GetAssetPath).ToArray(),boundsCenter=new[]{m.bounds.center.x,m.bounds.center.y,m.bounds.center.z},boundsSize=new[]{m.bounds.size.x,m.bounds.size.y,m.bounds.size.z}}));}File.WriteAllText(h+"lod_plan.json",plan.ToString());return new{exported=plan.Count};}
}
